package system

import (
	"errors"
	"fmt"
	"path/filepath"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// ErrNoComponents is returned when the workspace scan finds no scaffold
// record `sys create` can assemble into a component.
var ErrNoComponents = errors.New("no assemblable integration scaffolds found")

// Assemble classifies workspace scaffold records into a system model:
// shared-library records become the referenced contract project, records
// with a kind in the blockParsers registry become components, and
// everything else is skipped through warnf. The returned model's
// Name/ProjectName/SystemClass are left empty — the caller fills them
// around the template render.
func Assemble(entries []template.ScaffoldEntry, warnf func(format string, args ...any)) (*Model, error) {
	var (
		components []Component
		shared     []SharedLibrary
		byAppID    = map[string]string{}   // appId -> scaffold dir
		byTopic    = map[TopicKey]Topic{}  // key -> first-seen topic
		firstDir   = map[TopicKey]string{} // key -> dir that defined it
		byPort     = map[string]string{}   // port -> scaffold dir
	)

	for _, e := range entries {
		switch {
		case e.Role == template.RoleSharedLibrary:
			name, err := stringValue(e, "name")
			if err != nil {
				return nil, err
			}
			shared = append(shared, SharedLibrary{Path: e.Path, Name: name})
			continue
		case e.Role == template.RoleSystemHost:
			warnf("skipping %s: an existing system host", e.Path)
			continue
		case e.BlockKind == "":
			warnf("skipping %s: scaffold record has no block kind — re-scaffold with a newer template release to include it", e.Path)
			continue
		}

		parse, ok := blockParsers[e.BlockKind]
		if !ok {
			warnf("skipping %s: unsupported block kind %q (sys create assembles %s)", e.Path, e.BlockKind, strings.Join(supportedKinds(), ", "))
			continue
		}

		appID, err := stringValue(e, "appId")
		if err != nil {
			return nil, err
		}
		c := Component{AppID: appID, Kind: e.BlockKind, Path: e.Path}
		if err := parse(e, &c); err != nil {
			return nil, err
		}
		if c.missingPort {
			warnf("%s: scaffold record has no port — re-scaffold with a newer template release to wire From/To", e.Path)
		}

		if prev, ok := byAppID[appID]; ok {
			return nil, fmt.Errorf("duplicate component name %q: declared by both %s and %s (component names must be unique in a system)", appID, prev, e.Path)
		}
		byAppID[appID] = e.Path

		for _, port := range c.Ports {
			if prev, ok := byPort[port]; ok {
				return nil, fmt.Errorf("duplicate port %q: declared by both %s and %s (each block gets its own port; rename one in the record's values)", port, prev, e.Path)
			}
			byPort[port] = e.Path
		}

		if c.Topic != nil {
			key := *c.Topic
			if seen, ok := byTopic[key]; ok {
				if seen.Contract != c.topicContract {
					return nil, fmt.Errorf("topic %q on pubsub %q has conflicting contracts: %q (%s) vs %q (%s)", key.Name, key.Pubsub, seen.Contract, firstDir[key], c.topicContract, e.Path)
				}
			} else {
				byTopic[key] = Topic{TopicKey: key, Contract: c.topicContract}
				firstDir[key] = e.Path
			}
		}

		components = append(components, c)
	}

	if len(components) == 0 {
		return nil, fmt.Errorf("%w in this directory\nScaffold integrations first ('intropy int create <kind> -n <Name> ...'), then run 'intropy sys create' from the workspace root.", ErrNoComponents)
	}
	// Zero shared libraries is a valid workspace: a topic-free system never
	// references contracts, and a topic-bearing one gets them from the host
	// template's dependency. More than one is ambiguity the template cannot
	// resolve, so it stays an error regardless of the system's shape.
	if len(shared) > 1 {
		dirs := make([]string, len(shared))
		for i, s := range shared {
			dirs[i] = s.Path
		}
		return nil, fmt.Errorf("found %d shared contract projects (%s); a system host references exactly one — remove or consolidate before re-running", len(shared), strings.Join(dirs, ", "))
	}

	topics := make([]Topic, 0, len(byTopic))
	for _, t := range byTopic {
		topics = append(topics, t)
	}
	sort.Slice(topics, func(i, j int) bool {
		if topics[i].Pubsub != topics[j].Pubsub {
			return topics[i].Pubsub < topics[j].Pubsub
		}
		return topics[i].Name < topics[j].Name
	})

	ports := make([]Port, 0, len(byPort))
	for name := range byPort {
		ports = append(ports, Port{Name: name})
	}
	sort.Slice(ports, func(i, j int) bool { return ports[i].Name < ports[j].Name })

	model := &Model{Components: components, Topics: topics, Ports: ports}
	if len(shared) == 1 {
		model.Shared = &shared[0]
	}
	return model, nil
}

// stringValue returns values[key] as a non-empty string, with errors that
// name the record so the user knows which project to fix.
func stringValue(e template.ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(template.ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// stringValueDefault is stringValue with a fallback for records that
// predate the value being recorded.
func stringValueDefault(e template.ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return stringValue(e, key)
}

package system

import (
	"fmt"
	"sort"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// parseBlock reads one scaffold record's kind-specific values into the
// component's wiring. The parser owns per-record validation only; every
// cross-component check (topic contract conflicts, port uniqueness)
// stays in Assemble, gated on the component's shape.
type parseBlock func(e template.ScaffoldEntry, c *Component) error

// blockParsers is the set of block kinds Assemble accepts. Records with a
// kind absent from the registry are skipped with a warning naming the
// supported kinds. Adding a kind is a constant, a parser, and an entry here.
var blockParsers = map[string]parseBlock{
	template.BlockKindExtractor:     parseTopicBlock,
	template.BlockKindLoader:        parseTopicBlock,
	template.BlockKindTransactional: parseTransactional,
}

// supportedKinds lists the registry keys sorted, for the unsupported-kind
// warning.
func supportedKinds() []string {
	kinds := make([]string, 0, len(blockParsers))
	for k := range blockParsers {
		kinds = append(kinds, k)
	}
	sort.Strings(kinds)
	return kinds
}

// parseTopicBlock parses the wiring of a topic block (extractor, loader):
// a required topic and contract, and one optional port. A record without a
// port stays a valid component — it just gets no From/To in the generated
// wiring.
func parseTopicBlock(e template.ScaffoldEntry, c *Component) error {
	topic, err := stringValue(e, "topic")
	if err != nil {
		return err
	}
	contract, err := stringValue(e, "contract")
	if err != nil {
		return fmt.Errorf("%w\nRe-scaffold this integration with a template release that records the contract type, or add \"contract\": \"<TypeName>\" to the record's values.", err)
	}
	pubsub, err := stringValueDefault(e, "pubsub", "pubsub")
	if err != nil {
		return err
	}
	c.Topic = &TopicKey{Pubsub: pubsub, Name: topic}
	c.topicContract = contract

	// No fallback for the port: a default would describe a binding the
	// rendered code doesn't use. A missing key is reported by the caller as
	// a warning; a present one must be a non-empty string.
	if _, ok := e.Values["port"]; ok {
		port, err := stringValue(e, "port")
		if err != nil {
			return err
		}
		c.Port = port
		c.Ports = []string{port}
	} else {
		c.missingPort = true
	}
	return nil
}

// parseTransactional parses the wiring of a transactional block: exactly
// two ports, From before To, and no topic. Both ports are required — a
// half-wired transactional block would render broken code.
func parseTransactional(e template.ScaffoldEntry, c *Component) error {
	from, err := stringValue(e, "fromPort")
	if err != nil {
		return err
	}
	to, err := stringValue(e, "toPort")
	if err != nil {
		return err
	}
	c.Ports = []string{from, to}
	return nil
}

package system

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// ErrNoOrphans reports an update that found nothing to add. Callers can
// match it to suppress the message; the update itself prints the empty
// state and returns nil.
var ErrNoOrphans = errors.New("no orphaned components found")

// UpdateOptions configures Update. StartDir is the invocation directory —
// the workspace root, by the command's contract — and every writer has the
// same defaults as CreateOptions.
type UpdateOptions struct {
	StartDir   string
	Force      bool
	DryRun     bool
	OutputJSON string // "-" means stdout
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Template, Owner, Repo and Version override the pin the host's
	// scaffold record carries. Zero values render with exactly what
	// sys create pinned. GitHubBaseURL is a test-only seam.
	Template      string
	Owner         string
	Repo          string
	Version       string
	GitHubBaseURL string
}

// UpdateResult is the machine-readable summary --output json writes.
// Field names are stable and additive-only.
type UpdateResult struct {
	HostDir  string                 `json:"hostDir"`
	System   string                 `json:"system"`
	Added    []string               `json:"added"`
	Kept     []string               `json:"kept,omitempty"` // declared components whose scaffold is gone
	Files    []template.FileOutcome `json:"files,omitempty"`
	DryRun   bool                   `json:"dryRun"`
	Template string                 `json:"template,omitempty"`
	Owner    string                 `json:"owner,omitempty"`
	Repo     string                 `json:"repo,omitempty"`
	Version  string                 `json:"version,omitempty"`
}

// updatePlan is the pure half of an update: the located host, the baseline
// the host record stores, the orphans a workspace scan found, and the
// merged values a re-render consumes.
type updatePlan struct {
	hostDir  string             // host project directory, as located
	hostRec  *template.Scaffold // the host's own record
	baseline map[string]any     // the record's values, preserved verbatim
	orphans  []Component        // assemblable scaffolds the record does not declare
	kept     []string           // baseline appIds with no scaffold left
}

func (o *UpdateOptions) applyDefaults() {
	if o.StartDir == "" {
		o.StartDir = "."
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Update folds orphaned components — scaffolded integrations the host's
// record does not declare — into the workspace's system host. The declared
// baseline is the host record's stored values, never a re-scan, so a
// component whose scaffold disappeared stays declared. The record is
// rewritten last, after every declaration file landed, and never on a
// conflict, so a failed update retries against an honest baseline.
func Update(ctx context.Context, opts UpdateOptions) error {
	opts.applyDefaults()

	plan, err := planUpdate(opts)
	if err != nil {
		return err
	}
	if len(plan.orphans) == 0 {
		fmt.Fprintln(opts.Stderr, ErrNoOrphans.Error())
		return nil
	}
	for _, appID := range plan.kept {
		fmt.Fprintf(opts.Stderr, "note: component %s declared but no scaffold found — kept as declared\n", appID)
	}

	// The payload and the record rewrite both start from the record's own
	// values, so hand-recorded keys survive the round-trip untouched.
	merged := make(map[string]any, len(plan.baseline))
	for k, v := range plan.baseline {
		merged[k] = v
	}
	mergedComponents, err := mergedComponentEntries(plan)
	if err != nil {
		return err
	}
	merged["components"] = mergedComponents
	if err := mergeWiring(plan, merged); err != nil {
		return err
	}

	names := make([]string, len(plan.orphans))
	for i, c := range plan.orphans {
		names[i] = c.AppID
	}
	fmt.Fprintf(opts.Stderr, "updating %s: adding components %s\n", plan.hostDir, strings.Join(names, ", "))

	// The fetch resolves once against the merged payload; the baseline and
	// override payloads re-resolve against the same extracted library, so a
	// template override fetches what it renders and one download serves
	// all three resolutions.
	prep, err := template.PrepareCreate(ctx, template.CreateOptions{
		Template:      orDefault(opts.Template, plan.hostRec.Template),
		Version:       orDefault(opts.Version, plan.hostRec.Version),
		SetValues:     merged,
		NoInput:       true,
		OnManifest:    requireFactsPayload,
		Stdin:         strings.NewReader(""),
		Stdout:        opts.Stdout,
		Stderr:        opts.Stderr,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Owner:         orDefault(opts.Owner, plan.hostRec.Owner),
		Repo:          orDefault(opts.Repo, plan.hostRec.Repo),
		GitHubBaseURL: opts.GitHubBaseURL,
	})
	if err != nil {
		return err
	}
	defer prep.Cleanup()

	// The baseline is what the host was last rendered from; the render
	// decides per file whether a difference is the update itself (safe to
	// write) or a genuine divergence (a conflict). A template override
	// invalidates the baseline, so the strict comparison applies instead.
	var baseline map[string]any
	if opts.Template == "" && opts.Version == "" && (opts.Owner == "" || opts.Owner == plan.hostRec.Owner) && (opts.Repo == "" || opts.Repo == plan.hostRec.Repo) {
		baseline, err = template.Resolve(prep.Manifest, nil, strings.NewReader(""), plan.baseline, nil)
		if err != nil {
			fmt.Fprintf(opts.Stderr, "note: stored values do not re-resolve against %s@%s (%v) — treating every differing file as a conflict\n", prep.Template, prep.Version, err)
		}
	}

	outcomes, err := template.RenderUpdate(prep.SkeletonRoot, plan.hostDir, prep.Values, prep.Manifest.Spec.Files, template.RenderUpdateOptions{
		Force:    opts.Force,
		DryRun:   opts.DryRun,
		Baseline: baseline,
	})
	if err != nil {
		return err
	}
	if conflicts := conflictPaths(outcomes); len(conflicts) > 0 {
		return fmt.Errorf("declaration files differ from what the update would render: %s\nreconcile them by hand, or re-run with --force to overwrite", strings.Join(conflicts, ", "))
	}

	// The record goes last: a rerun after a partial failure must recompute
	// the same orphan set, which only an un-rewritten baseline guarantees.
	if !opts.DryRun {
		updated := *plan.hostRec
		updated.Values = merged
		if err := template.WriteScaffold(plan.hostDir, updated); err != nil {
			return err
		}
		fmt.Fprintf(opts.Stderr, "updated %s: added %d component(s)\n", plan.hostDir, len(plan.orphans))
		warnTopologyDrift(ctx, opts, plan, mergedComponents)
	}

	return maybeWriteUpdateResult(opts, plan, names, outcomes, prep)
}

// planUpdate locates the workspace's single system host and computes the
// orphan diff. Nothing is written; the scan root is the host's parent so a
// sibling scaffold is always seen, and running from inside the host
// directory is a clear error rather than a silently empty scan.
func planUpdate(opts UpdateOptions) (*updatePlan, error) {
	hosts, warnings := template.ListSystemHosts(opts.StartDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	switch len(hosts) {
	case 0:
		// A scaffold record in the invocation directory itself means the
		// user is standing in a project, not above one.
		if _, root, err := template.FindScaffold(opts.StartDir); err == nil {
			return nil, fmt.Errorf("%s is a scaffolded project, not a workspace\nrun 'intropy sys update' from the workspace root — the host's parent directory", root)
		}
		return nil, errors.New("no system host found in this directory\nrun 'intropy sys create' first, or run 'intropy sys update' from the workspace root")
	case 1:
	default:
		dirs := make([]string, len(hosts))
		for i, h := range hosts {
			dirs[i] = h.Path
		}
		return nil, fmt.Errorf("found %d system hosts (%s); 'sys update' updates exactly one — run it from a workspace with a single host", len(hosts), strings.Join(dirs, ", "))
	}
	host := hosts[0]

	// Running from inside the host means the sibling scan below sees
	// nothing; refuse rather than report a phantom no-op.
	absStart, err := filepath.Abs(opts.StartDir)
	if err != nil {
		return nil, err
	}
	absHost, err := filepath.Abs(host.Path)
	if err != nil {
		return nil, err
	}
	if rel, err := filepath.Rel(absHost, absStart); err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return nil, fmt.Errorf("%s is inside the system host %s\nrun 'intropy sys update' from the workspace root — the host's parent directory", opts.StartDir, host.Path)
	}

	// The baseline is the record's stored values: components, topics and
	// ports arrive as []any of map[string]any after the JSON round-trip.
	recordPath := filepath.Join(host.Path, filepath.FromSlash(template.ScaffoldRelPath))
	rawComponents, ok := host.Values["components"].([]any)
	if !ok {
		return nil, fmt.Errorf("%s: values.components is missing or not a list — the record does not match what sys create writes", recordPath)
	}
	declared := map[string]bool{}
	for _, c := range rawComponents {
		m, ok := c.(map[string]any)
		if !ok {
			return nil, fmt.Errorf("%s: values.components entry has type %T, expected object", recordPath, c)
		}
		appID, _ := m["appId"].(string)
		if appID == "" {
			return nil, fmt.Errorf("%s: values.components entry has no appId", recordPath)
		}
		declared[appID] = true
	}

	// Candidates come from the sibling scan; the host's parent is the
	// system root regardless of where below it the command was invoked.
	scanRoot := filepath.Dir(host.Path)
	entries, scanWarnings := template.ListScaffolds(scanRoot)
	for _, w := range scanWarnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	warnf := func(format string, args ...any) {
		fmt.Fprintf(opts.Stderr, "warning: "+format+"\n", args...)
	}
	model, err := assembleCandidates(entries, warnf)
	if err != nil {
		return nil, err
	}

	var orphans []Component
	for _, c := range model.Components {
		if !declared[c.AppID] {
			orphans = append(orphans, c)
		}
	}
	var kept []string
	present := map[string]bool{}
	for _, c := range model.Components {
		present[c.AppID] = true
	}
	for appID := range declared {
		if !present[appID] {
			kept = append(kept, appID)
		}
	}
	sort.Strings(kept)

	return &updatePlan{
		hostDir:  host.Path,
		hostRec:  &host.Scaffold,
		baseline: host.Values,
		orphans:  orphans,
		kept:     kept,
	}, nil
}

// assembleCandidates is Assemble without the zero-component refusal: an
// update against a workspace whose only scaffolds are already declared is
// a no-op, not an error.
func assembleCandidates(entries []template.ScaffoldEntry, warnf func(format string, args ...any)) (*Model, error) {
	model, err := Assemble(entries, warnf)
	if errors.Is(err, ErrNoComponents) {
		return &Model{}, nil
	}
	return model, err
}

// mergedComponentEntries appends each orphan's payload entry to the
// record's stored component list. The stored entries pass through
// untouched — that is what makes a vanished scaffold unable to remove its
// component.
func mergedComponentEntries(plan *updatePlan) ([]any, error) {
	stored, _ := plan.baseline["components"].([]any)
	merged := make([]any, 0, len(stored)+len(plan.orphans))
	merged = append(merged, stored...)
	for _, c := range plan.orphans {
		entry := map[string]any{
			"appId": c.AppID,
			"kind":  c.Kind,
		}
		if c.Topic != nil {
			entry["topic"] = map[string]any{
				"pubsub": c.Topic.Pubsub,
				"name":   c.Topic.Name,
			}
		}
		switch len(c.Ports) {
		case 0:
		case 1:
			entry["port"] = c.Ports[0]
		default:
			entry["fromPort"] = c.Ports[0]
			entry["toPort"] = c.Ports[1]
		}
		merged = append(merged, entry)
	}
	return merged, nil
}

// mergeWiring folds the orphans' topics and ports into the record's stored
// lists, deduplicating by (pubsub, name) and name respectively. A stored
// entry passes through verbatim; only genuinely new names are appended.
// Component payloads build their wiring against these lists, so an orphan
// naming a topic or port the host never declared must add it here.
func mergeWiring(plan *updatePlan, merged map[string]any) error {
	recordPath := filepath.Join(plan.hostDir, filepath.FromSlash(template.ScaffoldRelPath))

	type topicKey struct{ pubsub, name string }
	seenTopics := map[topicKey]bool{}
	storedTopics, _ := plan.baseline["topics"].([]any)
	topics := make([]any, 0, len(storedTopics))
	for _, t := range storedTopics {
		m, ok := t.(map[string]any)
		if !ok {
			return fmt.Errorf("%s: values.topics entry has type %T, expected object", recordPath, t)
		}
		pubsub, _ := m["pubsub"].(string)
		name, _ := m["name"].(string)
		seenTopics[topicKey{pubsub, name}] = true
		topics = append(topics, t)
	}

	seenPorts := map[string]bool{}
	storedPorts, _ := plan.baseline["ports"].([]any)
	ports := make([]any, 0, len(storedPorts))
	for _, p := range storedPorts {
		m, ok := p.(map[string]any)
		if !ok {
			return fmt.Errorf("%s: values.ports entry has type %T, expected object", recordPath, p)
		}
		name, _ := m["name"].(string)
		seenPorts[name] = true
		ports = append(ports, p)
	}

	// Each orphan contributes the wiring its scaffold record declared;
	// Assemble already deduplicated and cross-checked these against every
	// other scanned scaffold.
	for _, c := range plan.orphans {
		if c.Topic != nil {
			key := topicKey{c.Topic.Pubsub, c.Topic.Name}
			if !seenTopics[key] {
				seenTopics[key] = true
				topics = append(topics, map[string]any{
					"pubsub":   c.Topic.Pubsub,
					"name":     c.Topic.Name,
					"contract": c.topicContract,
				})
			}
		}
		for _, p := range c.Ports {
			if !seenPorts[p] {
				seenPorts[p] = true
				ports = append(ports, map[string]any{"name": p})
			}
		}
	}

	merged["topics"] = topics
	merged["ports"] = ports
	return nil
}

// conflictPaths lists the files the update refused to overwrite.
func conflictPaths(outcomes []template.FileOutcome) []string {
	var conflicts []string
	for _, o := range outcomes {
		if o.Outcome == template.OutcomeConflict {
			conflicts = append(conflicts, o.Path)
		}
	}
	return conflicts
}

// warnTopologyDrift runs the post-update advisory check: the host's graph
// output should now name every component the update declares. Every
// failure mode — no dotnet, a broken build, a disagreeing graph — is a
// stderr warning; the update itself already succeeded.
func warnTopologyDrift(ctx context.Context, opts UpdateOptions, plan *updatePlan, mergedComponents []any) {
	t, err := topology.RunGraph(ctx, plan.hostDir)
	if err != nil {
		fmt.Fprintf(opts.Stderr, "warning: topology check skipped: %v\n", err)
		return
	}
	graphed := map[string]bool{}
	for _, c := range t.Components {
		graphed[c.Name] = true
	}
	var missing []string
	for _, c := range mergedComponents {
		m := c.(map[string]any)
		appID, _ := m["appId"].(string)
		if !graphed[appID] {
			missing = append(missing, appID)
		}
	}
	if len(missing) > 0 {
		sort.Strings(missing)
		fmt.Fprintf(opts.Stderr, "warning: topology check: host graph does not declare %s — rebuild or check the rendered definitions\n", strings.Join(missing, ", "))
	}
}

func maybeWriteUpdateResult(opts UpdateOptions, plan *updatePlan, added []string, outcomes []template.FileOutcome, prep *template.PreparedCreate) error {
	if opts.OutputJSON == "" {
		return nil
	}
	absHost, err := filepath.Abs(plan.hostDir)
	if err != nil {
		absHost = plan.hostDir
	}
	result := UpdateResult{
		HostDir:  absHost,
		System:   prep.Values["name"].(string),
		Added:    added,
		Kept:     plan.kept,
		Files:    outcomes,
		DryRun:   opts.DryRun,
		Template: prep.Template,
		Owner:    prep.Owner,
		Repo:     prep.Repo,
		Version:  prep.Version,
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return fmt.Errorf("write --output: %w", err)
	}
	data = append(data, '\n')
	if opts.OutputJSON == "-" {
		if _, err := opts.Stdout.Write(data); err != nil {
			return fmt.Errorf("write --output: %w", err)
		}
		return nil
	}
	if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
		return fmt.Errorf("write --output: %w", err)
	}
	return nil
}

// orDefault picks the first non-empty string: an explicit flag over the
// record's pin.
func orDefault(flag, recorded string) string {
	if flag != "" {
		return flag
	}
	return recorded
}

package system

import (
	"fmt"
	"path/filepath"
)

// buildPayload assembles the value map passed as SetValues to the
// system-host template. The payload carries workspace facts only — topic and
// port names, component wiring, the detected contracts sibling — and the
// template derives everything that exists only inside the generated
// files: the Topics/Ports field identifiers, the joins between
// components and those fields, and the csproj ProjectReference path.
//
// The contracts sibling travels as a relative include: the template renders
// it verbatim into the host csproj's ProjectReference, and the host is
// always created as a sibling of the contracts project, so the CLI's
// workspace-relative path and the include differ only by the leading "../".
// Computing the include here keeps the templates (and the test fixtures that
// mirror them) free of host-side path arithmetic.
func buildPayload(m *Model, outputDir, kebab string) (map[string]any, error) {
	topics := make([]any, len(m.Topics))
	for i, t := range m.Topics {
		topics[i] = map[string]any{
			"pubsub":   t.Pubsub,
			"name":     t.Name,
			"contract": t.Contract,
		}
	}

	ports := make([]any, len(m.Ports))
	for i, c := range m.Ports {
		ports[i] = map[string]any{
			"name": c.Name,
		}
	}

	components := make([]any, len(m.Components))
	for i, c := range m.Components {
		// Kind is verbatim: Assemble already validated it against the
		// parse registry. The wiring fields follow the component's shape,
		// not its kind — a topic carries topic, one port port, two ports
		// fromPort/toPort — and the template resolves each name to the
		// field identifier it derived for the topic or port. The keys match
		// the transactional scaffold record's: the template library's
		// system-host reads fromPort/toPort (template release v0.4.0+).
		entry := map[string]any{
			"appId": c.AppID,
			"kind":  c.Kind,
		}
		if c.Topic != nil {
			entry["topic"] = map[string]any{
				"pubsub": c.Topic.Pubsub,
				"name":   c.Topic.Name,
			}
		}
		switch len(c.Ports) {
		case 0:
		case 1:
			entry["port"] = c.Ports[0]
		default:
			entry["fromPort"] = c.Ports[0]
			entry["toPort"] = c.Ports[1]
		}
		components[i] = entry
	}

	payload := map[string]any{
		"name":       kebab,
		"topics":     topics,
		"ports":      ports,
		"components": components,
	}
	if m.Shared != nil {
		include, err := contractsInclude(outputDir, *m.Shared)
		if err != nil {
			return nil, err
		}
		payload["sharedContracts"] = map[string]any{
			"name":    m.Shared.Name,
			"include": include,
		}
	}
	return payload, nil
}

// contractsInclude computes the ProjectReference Include path from the
// host's output directory to the shared library's csproj, slash-separated.
func contractsInclude(outputDir string, shared SharedLibrary) (string, error) {
	absOut, err := filepath.Abs(outputDir)
	if err != nil {
		return "", err
	}
	absShared, err := filepath.Abs(shared.Path)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absOut, absShared)
	if err != nil {
		return "", fmt.Errorf("compute path from %s to shared contracts project %s: %w", outputDir, shared.Path, err)
	}
	return filepath.ToSlash(filepath.Join(rel, shared.Name+".csproj")), nil
}

package template

import (
	"sort"
)

// TopicKey identifies a pub/sub topic within a workspace: the pub/sub
// component it lives on plus the topic name. It is the key workspace facts
// dedupe on — two scaffold records naming the same key declare the two
// halves of one contract.
//
// It is the canonical "which topic" shape for the whole CLI —
// internal/system aliases it for assembly — and its JSON tags are the
// wire vocabulary `sys create --output json` already serves.
type TopicKey struct {
	Pubsub string `json:"pubsub"`
	Name   string `json:"topic"`
}

// WorkspaceFacts is the prompt-time view of what a workspace's scaffold
// records already declare: the topics in use, the contract each carries,
// and the external ports already named, plus the one organization the
// records agree on. Create flows derive parameter
// suggestions from it; it is built by callers that scan workspaces
// (internal/system) and consumed read-only by value resolution.
//
// BuildWorkspaceFacts constructs one from scaffold entries; the zero value
// is a valid empty index.
type WorkspaceFacts struct {
	// TopicKeys holds the distinct topic keys in use, sorted by
	// (Pubsub, Topic).
	TopicKeys []TopicKey

	// Ports holds the distinct external port names in use, sorted
	// lexicographically.
	Ports []string

	// organization is the single organization the workspace's block records
	// declare. Records naming different organizations demote the fact — a
	// component belongs to exactly one organization, so a workspace that
	// disagrees with itself has nothing to suggest.
	organization string

	// contracts maps a topic key to its recorded contract type. A key whose
	// records disagree on the contract is absent — a conflicted fact is no
	// fact, and callers treat absence as "no suggestion".
	contracts map[TopicKey]string
}

// Organization returns the organization the workspace's block records
// agree on, or ("", false) when no record names one or they disagree.
func (f *WorkspaceFacts) Organization() (string, bool) {
	if f == nil || f.organization == "" {
		return "", false
	}
	return f.organization, true
}

// SetOrganization seeds the organization fact when the workspace has none.
// It is the caller's channel for context the records cannot carry — the
// resolved config's customer — and it never overrides a workspace-derived
// value: specific beats ambient. Call it before the facts feed Suggest.
func (f *WorkspaceFacts) SetOrganization(org string) {
	if f != nil && f.organization == "" {
		f.organization = org
	}
}

// ContractFor returns the contract type recorded for a topic key, or
// ("", false) when the key is unknown or its records conflict.
func (f *WorkspaceFacts) ContractFor(key TopicKey) (string, bool) {
	if f == nil {
		return "", false
	}
	c, ok := f.contracts[key]
	return c, ok
}

// WorkspaceFactEntry is the slice of a scaffold record fact-building reads:
// which block the record scaffolds and the values it recorded. Keeping the
// input this narrow lets BuildWorkspaceFacts stay in this package — a
// caller-side adapter maps full scaffold records to entries, and the import
// graph never cycles back through the scanner.
type WorkspaceFactEntry struct {
	// BlockKind is the record's block kind ("extractor", "loader",
	// "transactional-integration"); entries with any other kind contribute
	// nothing.
	BlockKind string

	// Values is the record's resolved parameter values.
	Values map[string]any
}

// BuildWorkspaceFacts indexes entries into workspace facts. It is
// deliberately lenient where Assemble is strict: entries with missing or
// mistyped wiring values are skipped rather than reported, because a
// suggestion aid must never fail an operation the records themselves would
// still allow. Organization is indexed from every entry with a block kind
// — a component's organization is not wiring — under the same conflict
// rule as contracts: one value wins, several demote the fact. The one
// cross-record rule it shares with Assemble is that conflicting contracts
// on one topic key demote the contract — suggesting either side of a
// conflict would bake a guess into the new record.
func BuildWorkspaceFacts(entries []WorkspaceFactEntry) *WorkspaceFacts {
	facts := &WorkspaceFacts{contracts: map[TopicKey]string{}}
	type contractSighting struct {
		contract   string
		conflicted bool
	}
	sightings := map[TopicKey]*contractSighting{}
	seenTopic := map[TopicKey]bool{}
	seenPort := map[string]bool{}
	orgSeen := false
	orgConflicted := false

	for _, e := range entries {
		if e.BlockKind == "" {
			continue
		}
		if org, ok := stringValue(e.Values, "organization"); ok {
			switch {
			case !orgSeen:
				orgSeen = true
				facts.organization = org
			case facts.organization != org:
				orgConflicted = true
			}
		}
		switch e.BlockKind {
		case BlockKindExtractor, BlockKindLoader:
			topic, tok := stringValue(e.Values, "topic")
			contract, cok := stringValue(e.Values, "contract")
			pubsub, _ := stringValue(e.Values, "pubsub")
			if pubsub == "" {
				pubsub = "pubsub"
			}
			if tok && cok {
				key := TopicKey{Pubsub: pubsub, Name: topic}
				if !seenTopic[key] {
					seenTopic[key] = true
					facts.TopicKeys = append(facts.TopicKeys, key)
				}
				if s, seen := sightings[key]; seen {
					if s.contract != contract {
						s.conflicted = true
					}
				} else {
					sightings[key] = &contractSighting{contract: contract}
				}
			}
			if port, ok := stringValue(e.Values, "port"); ok && !seenPort[port] {
				seenPort[port] = true
				facts.Ports = append(facts.Ports, port)
			}
		case BlockKindTransactional:
			for _, name := range []string{"fromPort", "toPort"} {
				if port, ok := stringValue(e.Values, name); ok && !seenPort[port] {
					seenPort[port] = true
					facts.Ports = append(facts.Ports, port)
				}
			}
		}
	}

	if orgConflicted {
		facts.organization = ""
	}
	for key, s := range sightings {
		if !s.conflicted {
			facts.contracts[key] = s.contract
		}
	}
	sort.Slice(facts.TopicKeys, func(i, j int) bool {
		if facts.TopicKeys[i].Pubsub != facts.TopicKeys[j].Pubsub {
			return facts.TopicKeys[i].Pubsub < facts.TopicKeys[j].Pubsub
		}
		return facts.TopicKeys[i].Name < facts.TopicKeys[j].Name
	})
	sort.Strings(facts.Ports)
	return facts
}

// stringValue reads values[key] as a non-empty string, reporting false for
// missing, mistyped, or empty values. Fact-building skips such entries
// rather than failing — the records may predate the value.
func stringValue(values map[string]any, key string) (string, bool) {
	s, ok := values[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

package template

// Suggest computes prompt-time candidate values for a template's declared
// fields from workspace facts and the values confirmed so far this run.
// The result is keyed by parameter name; fields the convention registry
// does not know, and fields with no candidates, are absent.
//
// The registry is CLI-owned convention, not manifest schema: it mirrors
// the value names the block templates record (topic, pubsub, contract —
// the same names internal/system's block parsers assemble from — plus
// organization, which the records carry without assembling). A template
// whose parameters use other names simply gets no suggestions.
//
// Ports are deliberately absent: every block needs its own port (system
// assembly rejects a shared one), so an already-taken port name is an
// anti-suggestion — offering it would steer scaffolds toward a collision.
//
// Suggestions are prompt metadata only. They never enter the values map on
// their own: a candidate becomes a value only when the prompter confirms
// it with the user, and callers record the confirmed value under the
// field's name — never the candidate list.
func Suggest(fields []FieldSpec, facts *WorkspaceFacts, confirmed map[string]any) map[string][]string {
	if facts == nil {
		return nil
	}
	out := map[string][]string{}
	for _, f := range fields {
		candidates := suggestField(f, facts, confirmed)
		candidates = dropDefaultCandidate(candidates, f)
		if len(candidates) > 0 {
			out[f.Name] = candidates
		}
	}
	return out
}

// suggestField is the convention registry: parameter name -> candidates
// derivable from the facts and the values confirmed so far. Chained
// derivation (contract follows the confirmed topic) re-reads the confirmed
// values on every call rather than threading field-to-field wiring, so the
// registry stays a flat name-to-rule table.
func suggestField(f FieldSpec, facts *WorkspaceFacts, confirmed map[string]any) []string {
	switch f.Name {
	case "organization":
		// One organization or none: a component belongs to exactly one, so
		// a conflicted workspace suggests nothing rather than listing
		// candidates that cannot all be right.
		if org, ok := facts.Organization(); ok {
			return []string{org}
		}
		return nil
	case "topic":
		topics := make([]string, 0, len(facts.TopicKeys))
		for _, key := range facts.TopicKeys {
			topics = append(topics, key.Name)
		}
		return topics
	case "pubsub":
		seen := map[string]bool{}
		var pubs []string
		for _, key := range facts.TopicKeys {
			if !seen[key.Pubsub] {
				seen[key.Pubsub] = true
				pubs = append(pubs, key.Pubsub)
			}
		}
		return pubs
	case "contract":
		// With a confirmed topic, the contract is constrained to it; a
		// conflicted or unknown key yields nothing rather than a guess.
		// Without one, every known contract is a candidate.
		if topic, ok := confirmedString(confirmed, "topic"); ok {
			pubsub, _ := confirmedString(confirmed, "pubsub")
			if pubsub == "" {
				pubsub = "pubsub"
			}
			if contract, ok := facts.ContractFor(TopicKey{Pubsub: pubsub, Name: topic}); ok {
				return []string{contract}
			}
			return nil
		}
		return knownContracts(facts)
	}
	return nil
}

// knownContracts lists every unconflicted contract the facts carry, in
// topic-key order with duplicates removed.
func knownContracts(facts *WorkspaceFacts) []string {
	seen := map[string]bool{}
	var out []string
	for _, key := range facts.TopicKeys {
		contract, ok := facts.ContractFor(key)
		if ok && !seen[contract] {
			seen[contract] = true
			out = append(out, contract)
		}
	}
	return out
}

// dropDefaultCandidate removes candidates the field's schema default
// already communicates — the prompt's default bracket and a suggestion
// list must never compete for the same value.
func dropDefaultCandidate(candidates []string, f FieldSpec) []string {
	def, ok := f.Default.(string)
	if !ok || def == "" {
		return candidates
	}
	out := candidates[:0]
	for _, c := range candidates {
		if c != def {
			out = append(out, c)
		}
	}
	return out
}

// confirmedString reads a confirmed value as a non-empty string. Confirmed
// values arrive from --set/--values/prompts and are already schema-coerced
// for declared fields; unknown or mistyped entries are treated as absent.
func confirmedString(confirmed map[string]any, key string) (string, bool) {
	s, ok := confirmed[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

package deploy

import (
	"encoding/json"
	"fmt"
	"maps"
	"path/filepath"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// The Kubernetes workload a block runs as.
//
// An extractor is scheduled: it wakes, pulls from its source and exits, which is
// a CronJob. Every other block reacts to messages or requests and must stay
// resident. This is what the hand-written customer repos already do — fluxia and
// entrovia both run their extractors as CronJobs — so deriving it from the
// topology is reproducing an existing convention, not inventing one.
const (
	WorkloadCronJob    = "cronjob"
	WorkloadDeployment = "deployment"
)

// blockKindExtractor is the topology's block kind for a scheduled extractor.
// Records spell kinds inconsistently (camelCase from one emitter, kebab-case
// after the frontend normalises), so the comparison folds case.
const blockKindExtractor = "extractor"

// ManifestModel is the topology view a manifest skeleton sees under the reserved
// "topology" key: derived, flattened and sorted.
//
// Raw topology.Topology is unsuitable for two reasons. Its APIs, Provides and
// Consumes are json.RawMessage whose element shape is not finalised, so a
// skeleton ranging over them would break when it is. And neither Go map
// iteration nor host emission order is stable, while repeatable rendering
// depends on a re-render being byte-identical — so everything here is sorted.
type ManifestModel struct {
	System     string              `json:"system"`
	Components []ManifestComponent `json:"components"`
	PubSubs    []ManifestPubSub    `json:"pubsubs"`
	Topics     []ManifestTopic     `json:"topics"`
	Ports      []ManifestPort      `json:"ports"`
}

// ManifestComponent is one block as the manifests need it.
type ManifestComponent struct {
	// Name is the topology component name, which is also the GitOps component
	// directory segment.
	Name string `json:"name"`

	// Kind is the topology block kind, carried through verbatim for labels.
	Kind string `json:"kind"`

	// AppID is the Dapr app-id: what a Component's scopes list and what the
	// generated C# resolves components by. Falls back to Name when no scaffold
	// record declares one.
	AppID string `json:"appId"`

	// Workload is WorkloadCronJob or WorkloadDeployment.
	Workload string `json:"workload"`

	// Dir is the component's source directory relative to the system root, when
	// a scaffold record was matched. Empty otherwise — a missing record is a
	// warning, not a failure, so the manifests still generate.
	Dir string `json:"dir,omitempty"`

	Topics []string `json:"topics,omitempty"`
	Ports  []string `json:"ports,omitempty"`
}

// ManifestPubSub is one Dapr pub/sub component the system needs.
type ManifestPubSub struct {
	Name   string   `json:"name"`
	Topics []string `json:"topics,omitempty"`

	// AppIDs is what belongs in the Component's scopes: every app-id the
	// topology says publishes to or subscribes from one of its topics.
	AppIDs []string `json:"appIds,omitempty"`
}

// ManifestTopic is a declared topic, with the ends resolved to app-ids.
type ManifestTopic struct {
	PubSub      string   `json:"pubsub"`
	Topic       string   `json:"topic"`
	Contract    string   `json:"contract,omitempty"`
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// ManifestPort is an external integration point. The topology mints only its
// name: the deployed Dapr binding's address, host and credentials are
// environment-owned deployment configuration, which is exactly why they are
// placeholders in the rendered manifests.
type ManifestPort struct {
	Name           string   `json:"name"`
	ExternalSystem string   `json:"externalSystem,omitempty"`
	Directions     []string `json:"directions,omitempty"`
	AppIDs         []string `json:"appIds,omitempty"`

	// Binding is the selected local fixture or GitOps binding kind for the
	// environment being rendered. Metadata remains GitOps-owned configuration.
	Binding string `json:"binding,omitempty"`
}

// newManifestModel derives the model from a decoded topology record and whatever
// scaffold records were found in the workspace.
func newManifestModel(t *topology.Topology, scaffolds []template.ScaffoldEntry) ManifestModel {
	appIDs, dirs := joinScaffolds(t.Components, matchScaffolds(t.Components, scaffolds))

	m := ManifestModel{System: t.System}
	m.Components = buildComponents(t.Components, appIDs, dirs)
	m.Topics = buildTopics(t.Topics, appIDs)
	m.PubSubs = buildPubSubs(t, appIDs)
	m.Ports = buildPorts(t.Ports, appIDs)
	return m
}

// asMap renders the model as plain maps and slices, with each port's binding
// set for the environment being rendered.
//
// Injected reserved values go through this so a skeleton's `index`, `range` and
// sprig calls see uniform map[string]any — a Go struct behaves differently
// under `index` and would make the template author's life needlessly subtle.
func (m ManifestModel) asMap(env string, bindings map[string]map[string]string) (map[string]any, error) {
	for i, c := range m.Ports {
		m.Ports[i].Binding = bindings[c.Name][env]
	}
	raw, err := json.Marshal(m)
	if err != nil {
		return nil, fmt.Errorf("encode topology model: %w", err)
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, fmt.Errorf("decode topology model: %w", err)
	}
	return out, nil
}

// bindingsForEnv reduces this render's choices to a flat port-to-binding map
// for compatibility with older local fixture templates.
func bindingsForEnv(model ManifestModel, bindings map[string]map[string]string, env string) map[string]string {
	out := make(map[string]string, len(model.Ports))
	for _, c := range model.Ports {
		if b := bindings[c.Name][env]; b != "" {
			out[c.Name] = b
		}
	}
	return out
}

// matchScaffolds pairs each topology component with its scaffold record.
//
// The join is by convention, and the toolchain uses two conventions: a
// component's directory basename, and its scaffold record's values.appId. Both
// are matched — directory first — because a record found by either is better
// than manifests generated without one. A component with no record is simply
// absent from the result: that is a warning, not a failure.
func matchScaffolds(components []topology.Component, scaffolds []template.ScaffoldEntry) map[string]template.ScaffoldEntry {
	byDir := make(map[string]template.ScaffoldEntry, len(scaffolds))
	byAppID := make(map[string]template.ScaffoldEntry, len(scaffolds))
	for _, s := range scaffolds {
		byDir[filepath.Base(s.Path)] = s
		if id := scaffoldString(s, "appId"); id != "" {
			byAppID[id] = s
		}
	}

	out := make(map[string]template.ScaffoldEntry, len(components))
	for _, c := range components {
		if match, found := byDir[c.Name]; found {
			out[c.Name] = match
			continue
		}
		if match, found := byAppID[c.Name]; found {
			out[c.Name] = match
		}
	}
	return out
}

// joinScaffolds reduces the matched records to the two facts the model needs.
func joinScaffolds(components []topology.Component, matched map[string]template.ScaffoldEntry) (appIDs, dirs map[string]string) {
	appIDs = make(map[string]string, len(components))
	dirs = make(map[string]string, len(components))
	for _, c := range components {
		match, found := matched[c.Name]
		if !found {
			continue
		}
		dirs[c.Name] = filepath.Base(match.Path)
		if id := scaffoldString(match, "appId"); id != "" {
			appIDs[c.Name] = id
		}
	}
	return appIDs, dirs
}

func scaffoldString(s template.ScaffoldEntry, key string) string {
	v, _ := s.Values[key].(string)
	return v
}

// appIDOf resolves a component name to an app-id.
//
// A name with no entry is returned unchanged. That covers two cases: a component
// with no scaffold record, and a name that is not a component of this system at
// all — Topic.Publishers and Topic.Subscribers may reference a block deployed
// elsewhere, and denying it access to the broker would be worse than scoping a
// name we cannot resolve.
func appIDOf(appIDs map[string]string, name string) string {
	if id, ok := appIDs[name]; ok {
		return id
	}
	return name
}

func buildComponents(components []topology.Component, appIDs, dirs map[string]string) []ManifestComponent {
	out := make([]ManifestComponent, 0, len(components))
	for _, c := range components {
		ic := ManifestComponent{
			Name:     c.Name,
			Kind:     c.Kind,
			AppID:    appIDOf(appIDs, c.Name),
			Workload: workloadFor(c.Kind),
			Dir:      dirs[c.Name],
		}

		topics := map[string]bool{}
		for _, s := range c.Subscribes {
			topics[s.Topic] = true
		}
		for _, p := range c.Publishes {
			topics[p.Topic] = true
		}
		ic.Topics = sortedKeys(topics)

		ports := map[string]bool{}
		for _, u := range c.Ports {
			ports[u.Port] = true
		}
		ic.Ports = sortedKeys(ports)

		out = append(out, ic)
	}
	slices.SortFunc(out, func(a, b ManifestComponent) int { return strings.Compare(a.Name, b.Name) })
	return out
}

// workloadFor maps a block kind to its Kubernetes workload. Anything that is not
// an extractor stays resident, which is the safe default: a block wrongly run as
// a CronJob would silently stop consuming.
func workloadFor(kind string) string {
	if strings.EqualFold(kind, blockKindExtractor) {
		return WorkloadCronJob
	}
	return WorkloadDeployment
}

func buildTopics(topics []topology.Topic, appIDs map[string]string) []ManifestTopic {
	out := make([]ManifestTopic, 0, len(topics))
	for _, t := range topics {
		out = append(out, ManifestTopic{
			PubSub:      t.PubSub,
			Topic:       t.Topic,
			Contract:    t.Contract,
			Publishers:  sortedAppIDs(appIDs, t.Publishers),
			Subscribers: sortedAppIDs(appIDs, t.Subscribers),
		})
	}
	slices.SortFunc(out, func(a, b ManifestTopic) int {
		if c := strings.Compare(a.PubSub, b.PubSub); c != 0 {
			return c
		}
		return strings.Compare(a.Topic, b.Topic)
	})
	return out
}

// buildPubSubs collects the distinct pub/sub components the system needs.
//
// Names are gathered from the top-level topics *and* from each component's
// inline references, because a component may publish to a topic the record's
// topics[] table does not list — and a pub/sub nobody declared is still one the
// sidecar will try to resolve.
func buildPubSubs(t *topology.Topology, appIDs map[string]string) []ManifestPubSub {
	topics := map[string]map[string]bool{}
	scopes := map[string]map[string]bool{}

	note := func(pubsub, topic string, users ...string) {
		if pubsub == "" {
			return
		}
		if topics[pubsub] == nil {
			topics[pubsub] = map[string]bool{}
			scopes[pubsub] = map[string]bool{}
		}
		if topic != "" {
			topics[pubsub][topic] = true
		}
		for _, u := range users {
			if u != "" {
				scopes[pubsub][appIDOf(appIDs, u)] = true
			}
		}
	}

	for _, top := range t.Topics {
		note(top.PubSub, top.Topic, append(slices.Clone(top.Publishers), top.Subscribers...)...)
	}
	for _, c := range t.Components {
		for _, s := range c.Subscribes {
			note(s.PubSub, s.Topic, c.Name)
		}
		for _, p := range c.Publishes {
			note(p.PubSub, p.Topic, c.Name)
		}
	}

	out := make([]ManifestPubSub, 0, len(topics))
	for _, name := range slices.Sorted(maps.Keys(topics)) {
		out = append(out, ManifestPubSub{
			Name:   name,
			Topics: sortedKeys(topics[name]),
			AppIDs: sortedKeys(scopes[name]),
		})
	}
	return out
}

func buildPorts(ports []topology.Port, appIDs map[string]string) []ManifestPort {
	out := make([]ManifestPort, 0, len(ports))
	for _, c := range ports {
		out = append(out, ManifestPort{
			Name:           c.Name,
			ExternalSystem: c.ExternalSystem,
			Directions:     slices.Sorted(slices.Values(c.Directions)),
			AppIDs:         sortedAppIDs(appIDs, c.UsedBy),
		})
	}
	slices.SortFunc(out, func(a, b ManifestPort) int { return strings.Compare(a.Name, b.Name) })
	return out
}

func sortedAppIDs(appIDs map[string]string, names []string) []string {
	if len(names) == 0 {
		return nil
	}
	set := make(map[string]bool, len(names))
	for _, n := range names {
		set[appIDOf(appIDs, n)] = true
	}
	return sortedKeys(set)
}

// sortedKeys returns a set's members in sorted order, or nil when empty so the
// omitempty JSON tags elide the field rather than emitting [].
func sortedKeys(set map[string]bool) []string {
	if len(set) == 0 {
		return nil
	}
	return slices.Sorted(maps.Keys(set))
}

package deploy

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/huandu/xstrings"
	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/interactive"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// The templates manifest generation renders. They are separate packages because they
// render a different number of times — once per system, once per component —
// into different directories, from different value sets.
const (
	TemplateDeployHost      = "deploy-host"
	TemplateDeployComponent = "deploy-component"
)

// HostDirName is the component directory holding a system's shared manifests.
//
// A Dapr Component is namespace-scoped and every integration in a customer's
// namespace shares it, so exactly one ArgoCD Application may own each one. The
// system host is what gives them that owner: it has no Dockerfile and therefore
// no image, which is precisely what gitops.KindShared describes.
const HostDirName = "host"

// Review branches keep incomplete manifests away from the default branch,
// where the ApplicationSet could pick them up before review.
const manifestsCreateBranchPrefix = "manifests-create/"

// runGraph is the seam tests replace to avoid a dotnet build.
var runGraph = topology.RunGraph

// manifestMode selects where a scaffold lands.
type manifestMode int

const (
	// modeGitOps scaffolds into the GitOps repository and pushes a review
	// branch. The default.
	modeGitOps manifestMode = iota

	// modeLocal renders for the local development cluster and returns the
	// complete built manifest stream. Nothing touches Git.
	modeLocal
)

// manifestRunOptions carries the shared inputs after a manifests command has
// applied its own flag and side-effect policy.
//
// There is no Environment: overlays are created for every environment the
// repository defines unless Environments narrows it. There is no AllowDirty, no
// NoWait and no Timeout either — no source working tree is read for correctness,
// and nothing is synced.
type manifestRunOptions struct {
	// Mode selects the destination. modeLocal renders for the local
	// development cluster instead of scaffolding the GitOps tree.
	Mode manifestMode

	// Namespace is the target namespace a local render emits. Empty defaults
	// to the system name. GitOps mode rejects it: the namespace there is the
	// templates' namespace/namespacePerEnv parameters.
	Namespace string

	// Images overrides image references in a local render, repeatable.
	// "<component>=<name:tag>" overrides one component's entry; ":<tag>"
	// (leading colon) retags every component — the release-candidate flow.
	// GitOps mode rejects them: `intropy deploy` pins digests, and scaffolding
	// never pins one.
	Images []string

	// Bindings supplies local port-to-fixture choices. Selector asks for
	// choices omitted from Bindings when terminal interaction is available.
	Bindings []string
	Selector interactive.Selector
	// Domain places the system in the GitOps tree. Unlike every other deploy
	// subcommand's --domain this is a destination rather than a filter. Empty is
	// inferred when exactly one domain already holds the system.
	Domain string

	// System names the system to scaffold.
	//
	// It does two things, which are the same thing said once: it selects which
	// system host to read the topology from when a workspace holds several, and
	// it is the tree segment. Empty means the only host in the workspace, named
	// by whatever its topology declares.
	System string

	// Environments selects which overlays to create. Empty means every
	// environment in deploy.yaml — and in local mode exactly the local
	// environment, whatever deploy.yaml says.
	Environments []string

	// TopologyFile reads the record from a file instead of running the host's
	// graph verb; "-" reads stdin. Internal test seam — not exposed as a CLI flag.
	TopologyFile string

	// SourceDir is where system hosts and scaffold records are discovered.
	// Internal test seam — not exposed as a CLI flag.
	SourceDir string

	// TemplateVersion pins the template library release.
	TemplateVersion string

	// Stdin is used only by the topology-file test seam. Manifest commands do
	// not prompt or accept ad-hoc value layers.
	Stdin io.Reader

	// PlanOnly resolves, renders and classifies, then reports without creating
	// manifest files, commits, or pushes.
	PlanOnly bool

	GitopsRepo   string
	OutputFormat string
	Color        bool
	CacheRoot    string

	Runner     command.Runner
	UserAgent  string
	CliVersion string
	Stdout     io.Writer
	Stderr     io.Writer

	// Owner and Repo select the template library; zero values target the
	// official library. GitHubBaseURL is a test-only seam.
	Owner         string
	Repo          string
	GitHubBaseURL string
	HTTP          *http.Client

	// The manifests create command sets these internal policy fields. Keeping
	// them private prevents another deploy operation from enabling create-only
	// behavior accidentally.
	diffOnly  bool
	reviewEnv string
}

func (o manifestRunOptions) output() output {
	return output{Format: o.OutputFormat, Color: o.Color, Stdout: o.Stdout, Stderr: o.Stderr}
}

func (o manifestRunOptions) session() sessionOptions {
	return sessionOptions{
		GitopsRepo: o.GitopsRepo,
		CacheRoot:  o.CacheRoot,
		Runner:     o.Runner,
		Stderr:     o.Stderr,
	}
}

func (o *manifestRunOptions) applyDefaults() {
	if o.Runner == nil {
		o.Runner = git.DefaultRunner()
	}
	if o.SourceDir == "" {
		o.SourceDir = "."
	}
	if o.OutputFormat == "" {
		o.OutputFormat = OutputPlain
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
}

// renderLocalManifests resolves port bindings, stages the local tree,
// applies namespace and image overrides through a root kustomization, and
// returns the complete build. It never inspects or changes a cluster.
func renderLocalManifests(ctx context.Context, opts manifestRunOptions, found discoveredTopology, lib *template.Library) ([]byte, error) {
	overrides, err := parseImageOverrides(opts.Images)
	if err != nil {
		return nil, err
	}

	facts, err := resolveLocalFacts(opts, found)
	if err != nil {
		return nil, err
	}
	namespace := opts.Namespace
	if namespace == "" {
		namespace = facts.System
	}

	bindings, err := resolveLocalPortBindings(ctx, opts, facts, lib)
	if err != nil {
		return nil, err
	}

	staging, err := os.MkdirTemp("", "intropy-manifests-render-*")
	if err != nil {
		return nil, fmt.Errorf("create staging directory: %w", err)
	}
	defer os.RemoveAll(staging)

	fmt.Fprintf(opts.Stderr, "rendering %s for local\n", facts.System)
	if err := renderScaffold(ctx, opts, facts, bindings, lib, staging); err != nil {
		return nil, err
	}

	images, err := localImageEntries(facts, overrides)
	if err != nil {
		return nil, err
	}
	if err := writeLocalRootKustomization(staging, namespace, facts, images); err != nil {
		return nil, err
	}

	built, err := kustomizeBuild(ctx, opts.Runner, staging)
	if err != nil {
		return nil, err
	}
	if err := assertAllImagesTagged(built); err != nil {
		return nil, err
	}
	return built, nil
}

// initGitOps is the modeGitOps publish path: render the repo-relative staging
// tree, classify every file against the checkout, and push the result on a
// review branch.
func initGitOps(ctx context.Context, opts manifestRunOptions, found discoveredTopology, lib *template.Library) error {
	out := opts.output()

	s, err := openSession(ctx, opts.session(), "git")
	if err != nil {
		return err
	}
	defer s.Close()

	facts, err := resolveGitOpsFacts(opts, s, found)
	if err != nil {
		return err
	}

	bindings := map[string]map[string]string{}
	if len(facts.Model.Ports) > 0 {
		bindings, err = resolveGitOpsPortBindings(ctx, opts, facts, lib)
		if err != nil {
			return err
		}
	}

	staging, err := os.MkdirTemp("", "intropy-manifests-create-*")
	if err != nil {
		return fmt.Errorf("create staging directory: %w", err)
	}
	defer os.RemoveAll(staging)

	// Opened once, and every read of and write to the checkout goes through it:
	// the manifests come from a repository this CLI does not control, and the
	// tree segments come from flags.
	dest, err := openDestTree(s.repo.Root)
	if err != nil {
		return err
	}
	defer dest.Close()

	if err := renderScaffold(ctx, opts, facts, bindings, lib, staging); err != nil {
		return err
	}
	branch := manifestsCreateBranchPrefix + facts.Domain + "-" + facts.System + "-" + opts.reviewEnv

	rels, err := stageRels(staging)
	if err != nil {
		return err
	}
	actions, err := classifyStaged(staging, dest, rels)
	if err != nil {
		return err
	}
	if opts.diffOnly {
		return reportManifestCreateDiff(out.Stdout, staging, dest, actions)
	}
	if err := refuseManifestReplacements(actions); err != nil {
		return err
	}

	result := ManifestCreateResult{
		System:       facts.System,
		Domain:       facts.Domain,
		Host:         HostDirName,
		Template:     lib.Ref(),
		Components:   facts.ComponentNames(),
		Files:        actions,
		Applied:      false,
		Placeholders: nil,
	}

	if opts.PlanOnly {
		// Scan the staging tree: the files are not in the repository yet, so the
		// only place the placeholders exist is where they were rendered.
		result.Placeholders, err = scanPlaceholders(staging, rels)
		if err != nil {
			return err
		}
		return reportManifestCreate(out, result, actions, true)
	}

	if writes(actions) == 0 {
		// Nothing to write, but the placeholders already in the repository are
		// still the answer to "what is left to do here".
		result.Placeholders, err = scanPlaceholders(s.repo.Root, rels)
		if err != nil {
			return err
		}
		return reportManifestCreate(out, result, actions, false)
	}

	published, err := publishScaffold(ctx, opts, s.repo, publishScaffoldOptions{
		StagingDir: staging,
		Dest:       dest,
		Actions:    actions,
		Rels:       rels,
		Branch:     branch,
		Facts:      facts,
	})
	if err != nil {
		return err
	}
	result.Applied = true
	result.Branch = branch
	result.Revision = published.Revision
	result.Placeholders = published.Placeholders

	return reportManifestCreate(out, result, actions, false)
}

// resolveLocalFacts is resolveGitOpsFacts with local constants in place of the
// GitOps checkout's facts — newLocalFacts plus the selection and validation
// the GitOps path does on the way.
func resolveLocalFacts(opts manifestRunOptions, found discoveredTopology) (manifestFacts, error) {
	topo := found.Topology

	system := opts.System
	if system == "" {
		system = topo.System
	}
	if system == "" {
		return manifestFacts{}, fmt.Errorf("the topology record names no system; pass --system")
	}
	if err := assertPathSegment("--system", system); err != nil {
		return manifestFacts{}, err
	}

	model := newManifestModel(topo, found.Scaffolds)
	selected := slices.Clone(model.Components)
	for _, c := range selected {
		// From the topology record, which is generated by a build this CLI does
		// not own: a name with a separator in it would render into a directory of
		// its own choosing.
		if err := assertPathSegment("component name", c.Name); err != nil {
			return manifestFacts{}, err
		}
		if c.Dir == "" {
			fmt.Fprintf(opts.Stderr, "warning: %s has no scaffold record under the workspace root; its manifests will be generated without an appId or sourcePaths\n", c.Name)
		}
	}

	return newLocalFacts(system, model, matchScaffolds(topo.Components, found.Scaffolds), selected), nil
}

func writes(actions []FileAction) int {
	n := 0
	for _, a := range actions {
		if a.Writes() {
			n++
		}
	}
	return n
}

// discoveredTopology is what discoverManifestTopology found in the workspace.
type discoveredTopology struct {
	Topology  *topology.Topology
	Scaffolds []template.ScaffoldEntry

	// HostDir is the system host the record came from. Its path is the best
	// source for the domain.
	HostDir string
}

// discoverManifestTopology obtains the record and the workspace's scaffold records.
func discoverManifestTopology(ctx context.Context, opts manifestRunOptions) (discoveredTopology, error) {
	scaffolds, warnings := template.ListScaffolds(opts.SourceDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}

	if opts.TopologyFile != "" {
		r := opts.Stdin
		if opts.TopologyFile != "-" {
			f, err := os.Open(opts.TopologyFile)
			if err != nil {
				return discoveredTopology{}, fmt.Errorf("read topology: %w", err)
			}
			defer f.Close()
			r = f
		}
		topo, err := topology.Decode(r)
		if err != nil {
			return discoveredTopology{}, fmt.Errorf("read topology %s: %w", opts.TopologyFile, err)
		}
		return discoveredTopology{Topology: topo, Scaffolds: scaffolds}, nil
	}

	var hosts []template.ScaffoldEntry
	for _, s := range scaffolds {
		if s.Role == template.RoleSystemHost {
			hosts = append(hosts, s)
		}
	}
	host, err := selectHost(hosts, opts.System, opts.SourceDir)
	if err != nil {
		return discoveredTopology{}, err
	}

	// Said before starting, not after: a silent multi-minute wait reads as a hang.
	fmt.Fprintf(opts.Stderr, "reading topology from %s (building first; this can take a minute)\n", host.Path)
	topo, err := runGraph(ctx, host.Path)
	if err != nil {
		return discoveredTopology{}, fmt.Errorf("%s: %w", host.Path, err)
	}
	if opts.System != "" && topo.System != "" && opts.System != topo.System {
		// Not an error: --system names the system, and a caller who asked for a
		// different name gets it. Worth saying out loud, because it silently
		// decides the tree segment.
		fmt.Fprintf(opts.Stderr, "warning: the topology declares system %q; using %q as the tree segment\n", topo.System, opts.System)
	}
	return discoveredTopology{Topology: topo, Scaffolds: scaffolds, HostDir: host.Path}, nil
}

// selectHost picks which system host to read the topology from.
//
// Selection is by name and costs nothing: a scaffolded host records the system
// name in its own record, and its parent directory is the system directory. Both
// are on disk, so a multi-system workspace does not have to build every host to
// find out which one was meant.
//
// With no --system and one host, that host. With no --system and several, an
// error — picking one arbitrarily would scaffold the wrong system.
func selectHost(hosts []template.ScaffoldEntry, system, sourceDir string) (template.ScaffoldEntry, error) {
	if len(hosts) == 0 {
		return template.ScaffoldEntry{}, fmt.Errorf("no system host found under %s; run this from a system workspace", sourceDir)
	}

	if system != "" {
		var matches []template.ScaffoldEntry
		for _, h := range hosts {
			if matchesSystemName(h, system) {
				matches = append(matches, h)
			}
		}
		switch len(matches) {
		case 1:
			return matches[0], nil
		case 0:
			// A single host and no match is the older meaning of --system: rename
			// the tree segment rather than select anything. Still useful, and
			// unambiguous when there is only one system to talk about.
			if len(hosts) == 1 {
				return hosts[0], nil
			}
			return template.ScaffoldEntry{}, fmt.Errorf("no system host named %q under %s.\nFound:\n%s",
				system, sourceDir, describeHosts(hosts))
		default:
			return template.ScaffoldEntry{}, fmt.Errorf("%q matches %d system hosts, so it does not say which one:\n%s",
				system, len(matches), describeHosts(matches))
		}
	}

	if len(hosts) == 1 {
		return hosts[0], nil
	}
	return template.ScaffoldEntry{}, fmt.Errorf("%s holds %d system hosts; pass --system to pick one:\n%s",
		sourceDir, len(hosts), describeHosts(hosts))
}

// matchesSystemName reports whether a host is the one the caller named.
//
// Three keys are tried, in descending reliability: the record's own name (what
// sys create writes), the system directory holding the host, and the host
// directory itself — which is often a generic "system-host" and so the weakest.
func matchesSystemName(h template.ScaffoldEntry, system string) bool {
	want := normalizeSystemName(system)
	keys := []string{
		scaffoldString(h, "name"),
		filepath.Base(filepath.Dir(h.Path)),
		filepath.Base(h.Path),
	}
	for _, k := range keys {
		if k != "" && normalizeSystemName(k) == want {
			return true
		}
	}
	return false
}

// normalizeSystemName folds the spellings that mean the same system. sys create
// kebab-cases whatever it is given, so OrderFlow and order-flow are the same
// system and must select the same host.
func normalizeSystemName(s string) string {
	return strings.ToLower(xstrings.ToKebabCase(s))
}

func describeHosts(hosts []template.ScaffoldEntry) string {
	lines := make([]string, 0, len(hosts))
	for _, h := range hosts {
		name := scaffoldString(h, "name")
		if name == "" {
			name = filepath.Base(filepath.Dir(h.Path))
		}
		lines = append(lines, fmt.Sprintf("  %s  (%s)", name, h.Path))
	}
	slices.Sort(lines)
	return strings.Join(lines, "\n")
}

// manifestFacts is everything derived before rendering: where the manifests go, what
// the platform is, and the model the skeletons range over.
type manifestFacts struct {
	Domain string
	System string

	Environments []string
	Registry     string
	AppNamespace string
	Platform     gitops.PlatformConfig

	Model     ManifestModel
	Scaffolds map[string]template.ScaffoldEntry
	Selected  []ManifestComponent
}

func (f manifestFacts) ComponentNames() []string {
	names := make([]string, 0, len(f.Selected))
	for _, c := range f.Selected {
		names = append(names, c.Name)
	}
	return names
}

func resolveGitOpsFacts(opts manifestRunOptions, s *session, found discoveredTopology) (manifestFacts, error) {
	topo, scaffolds := found.Topology, found.Scaffolds

	system := opts.System
	if system == "" {
		system = topo.System
	}
	if system == "" {
		return manifestFacts{}, fmt.Errorf("the topology record names no system; pass --system")
	}

	domain, err := resolveManifestDomain(s.repo.Root, opts.Domain, system, found.HostDir, scaffolds, opts.Stderr)
	if err != nil {
		return manifestFacts{}, err
	}

	// Both become tree segments and both end up in the branch name, so neither
	// may be anything but a single name. destTree refuses a traversal at the
	// write; failing here instead names the input that was wrong.
	if err := assertPathSegment("--domain", domain); err != nil {
		return manifestFacts{}, err
	}
	if err := assertPathSegment("--system", system); err != nil {
		return manifestFacts{}, err
	}

	environments, err := selectEnvironments(s.deployCfg, opts.Environments)
	if err != nil {
		return manifestFacts{}, err
	}

	model := newManifestModel(topo, scaffolds)
	selected := slices.Clone(model.Components)
	for _, c := range selected {
		// From the topology record, which is generated by a build this CLI does
		// not own: a name with a separator in it would render into a directory of
		// its own choosing.
		if err := assertPathSegment("component name", c.Name); err != nil {
			return manifestFacts{}, err
		}
		if c.Dir == "" {
			fmt.Fprintf(opts.Stderr, "warning: %s has no scaffold record under the workspace root; its manifests will be generated without an appId or sourcePaths\n", c.Name)
		}
	}

	return manifestFacts{
		Domain:       domain,
		System:       system,
		Environments: environments,
		Registry:     s.deployCfg.Registry,
		AppNamespace: s.deployCfg.Argocd.AppNamespace,
		Platform:     s.deployCfg.Platform,
		Model:        model,
		Scaffolds:    matchScaffolds(topo.Components, scaffolds),
		Selected:     selected,
	}, nil
}

// resolveManifestDomain places the system in the tree.
//
// The topology itself says nothing about which business domain a system belongs
// to, but two other things do, and between them --domain is rarely needed:
//
//   - where the system already is in the GitOps tree, which is authoritative —
//     a re-run must land where the component actually lives;
//   - the source workspace's own layout, which every customer integrations tree
//     mirrors from the deployment tree: domains/<domain>/<system>/<project>.
//
// An explicit --domain always wins, and is still required when neither holds.
func resolveManifestDomain(root, flag, system, hostDir string, scaffolds []template.ScaffoldEntry, stderr io.Writer) (string, error) {
	if flag != "" {
		return flag, nil
	}

	inTree := domainsHoldingSystem(root, system)
	fromWorkspace := domainFromWorkspaceLayout(hostDir, scaffolds)

	switch len(inTree) {
	case 1:
		// The repository wins over the workspace: moving a system between domains
		// is a deliberate act, not something a directory name should trigger.
		if fromWorkspace != "" && fromWorkspace != inTree[0] {
			fmt.Fprintf(stderr, "warning: %s is already under %s/%s in the GitOps repository, but the workspace suggests %q; keeping %s — pass --domain to move it deliberately\n",
				system, gitops.DomainsDirName, inTree[0], fromWorkspace, inTree[0])
		}
		return inTree[0], nil
	case 0:
		if fromWorkspace != "" {
			fmt.Fprintf(stderr, "placing %s under %s/%s, from the workspace layout\n", system, gitops.DomainsDirName, fromWorkspace)
			return fromWorkspace, nil
		}
		return "", fmt.Errorf("--domain is required: %s is not in the GitOps repository yet, and the workspace is not laid out as %s/<domain>/%s/, so there is no domain to infer",
			system, gitops.DomainsDirName, system)
	default:
		return "", fmt.Errorf("--domain is required: %s exists under %s", system, strings.Join(inTree, " and "))
	}
}

// domainsHoldingSystem lists the domains the GitOps tree already files this
// system under, sorted. More than one means the name is ambiguous.
func domainsHoldingSystem(root, system string) []string {
	var found []string
	for _, c := range gitops.ListComponents(root) {
		if c.System == system && !slices.Contains(found, c.Domain) {
			found = append(found, c.Domain)
		}
	}
	slices.Sort(found)
	return found
}

// domainFromWorkspaceLayout reads the domain out of the source tree's own shape.
//
// The system host is tried first because it is the system's own directory; a
// block is only a fallback for the --topology case, where no host was discovered.
func domainFromWorkspaceLayout(hostDir string, scaffolds []template.ScaffoldEntry) string {
	if d := domainFromProjectPath(hostDir); d != "" {
		return d
	}
	for _, s := range scaffolds {
		if d := domainFromProjectPath(s.Path); d != "" {
			return d
		}
	}
	return ""
}

// domainFromProjectPath returns the <domain> in
// <...>/domains/<domain>/<system>/<project>, or empty when the path is not laid
// out that way.
//
// The marker directory has to actually be there — gitops.DomainsDirName, the same
// constant the deployment tree uses. Without it nothing is inferred, so a
// workspace with some other shape gets a clear "--domain is required" rather than
// a guess.
func domainFromProjectPath(projectDir string) string {
	if projectDir == "" {
		return ""
	}
	abs, err := filepath.Abs(projectDir)
	if err != nil {
		abs = projectDir
	}
	domainDir := filepath.Dir(filepath.Dir(abs))
	if filepath.Base(filepath.Dir(domainDir)) != gitops.DomainsDirName {
		return ""
	}
	name := filepath.Base(domainDir)
	if name == "." || name == string(filepath.Separator) || name == gitops.DomainsDirName {
		return ""
	}
	return name
}

func selectEnvironments(cfg *gitops.DeployConfig, requested []string) ([]string, error) {
	all := len(requested) == 0
	if all {
		// Every environment, in promotion order. The ApplicationSet takes the
		// environment from its cluster generator rather than the path, so an
		// environment without an overlay is an Application pointing at nothing.
		requested = cfg.PromotionOrder()
	}
	for _, env := range requested {
		if _, err := cfg.Environment(env); err != nil {
			return nil, err
		}
		if err := assertPathSegment("environment name", env); err != nil {
			return nil, err
		}
	}
	out := slices.Clone(requested)
	if all {
		return out, nil
	}
	slices.Sort(out)
	return slices.Compact(out), nil
}

// renderScaffold renders the host template once and the component template once
// per selected component.
//
// In GitOps mode staging mirrors the repository, so a staged path is already
// the repo-relative path the classifier and the commit both need. A local
// render stages flat — host/ and one directory per component — because the
// temp root already holds exactly one system and no commit needs a
// repo-relative path.
func renderScaffold(ctx context.Context, opts manifestRunOptions, facts manifestFacts, bindings map[string]map[string]string, lib *template.Library, staging string) error {
	if err := renderOne(opts, facts, bindings, lib, TemplateDeployHost, HostDirName, nil, staging); err != nil {
		return err
	}
	for _, c := range facts.Selected {
		comp := c
		if err := renderOne(opts, facts, bindings, lib, TemplateDeployComponent, c.Name, &comp, staging); err != nil {
			return err
		}
	}
	return nil
}

// renderOne renders one unit — the host, or one component — into the staging
// tree.
//
// The skeleton is rendered once per environment, because the renderer templates
// paths but does not iterate them, so `overlays/{{ .env }}/kustomization.yaml` is
// the only way to get one directory per environment. mergeRendered then enforces
// that everything outside overlays/ came out identical on every pass.
func renderOne(opts manifestRunOptions, facts manifestFacts, bindings map[string]map[string]string, lib *template.Library, templateName, dirName string, comp *ManifestComponent, staging string) error {
	tmpl, skeleton, err := lib.Open(templateName)
	if err != nil {
		return err
	}

	// GitOps mode stages the repository-relative path; a local render is flat.
	dest := filepath.Join(staging, dirName)
	if opts.Mode != modeLocal {
		dest = filepath.Join(staging, filepath.FromSlash(componentRelPath(facts.Domain, facts.System, dirName)))
	}
	if err := os.MkdirAll(dest, 0o755); err != nil {
		return err
	}

	rules := tmpl.Spec.Files
	if opts.Mode == modeLocal {
		rules = localFileRules(rules)
	} else {
		rules = gitOpsFileRules(rules)
	}
	for _, env := range facts.Environments {
		values, err := resolveManifestValues(opts, facts, bindings, tmpl, dirName, comp, env)
		if err != nil {
			return fmt.Errorf("%s for %s: %w", templateName, dirName, err)
		}

		pass, err := os.MkdirTemp("", "intropy-render-*")
		if err != nil {
			return err
		}
		err = template.RenderFiltered(skeleton, pass, values, rules)
		if err == nil {
			err = mergeRendered(pass, dest, env)
		}
		os.RemoveAll(pass)
		if err != nil {
			return fmt.Errorf("render %s for %s (%s): %w", templateName, dirName, env, err)
		}
	}
	return nil
}

// resolveManifestValues layers the derived facts under the user's input, then injects
// the structures spec.parameters cannot describe.
//
// Facts beat schema defaults; the user beats facts. That order is the whole point
// of ResolveLayered, and this is its first production caller.
func resolveManifestValues(opts manifestRunOptions, facts manifestFacts, bindings map[string]map[string]string, tmpl *template.Template, dirName string, comp *ManifestComponent, env string) (map[string]any, error) {
	base := seedDeclaredParams(tmpl, manifestSeeds(facts, dirName, comp))

	prompter := template.AutoPrompter(opts.Stdin, opts.Stderr, true)
	values, err := template.ResolveLayered(tmpl, base, nil, opts.Stdin, nil, prompter)
	if err != nil {
		return nil, err
	}

	model, err := facts.Model.asMap(env, bindings)
	if err != nil {
		return nil, err
	}
	reserved := map[string]any{
		template.ReservedEnvKey:      env,
		template.ReservedTopologyKey: model,
		template.ReservedGitopsKey:   facts.gitopsMap(dirName, env),
	}
	if env == localEnv {
		// Deprecated: the ports' binding field carries the same fact. Kept
		// so a library older than that field still renders its fixture overlay;
		// remove when the floor template version has moved past it.
		local, err := toMap(localModel{Bindings: bindingsForEnv(facts.Model, bindings, env)})
		if err != nil {
			return nil, err
		}
		reserved[template.ReservedLocalKey] = local
	}
	if comp != nil {
		componentMap, err := toMap(comp)
		if err != nil {
			return nil, err
		}
		reserved[template.ReservedComponentKey] = componentMap
		reserved[template.ReservedScaffoldKey] = facts.scaffoldValues(comp.Name)
	}
	if err := template.InjectReserved(tmpl, values, reserved); err != nil {
		return nil, err
	}
	return values, nil
}

// manifestSeeds is every fact the CLI can derive, keyed by the parameter name a
// template would declare for it.
func manifestSeeds(facts manifestFacts, dirName string, comp *ManifestComponent) map[string]any {
	seeds := map[string]any{
		"domain":             facts.Domain,
		"system":             facts.System,
		"hostName":           HostDirName,
		"registry":           facts.Registry,
		"argocdAppNamespace": facts.AppNamespace,
		"provider":           facts.Platform.Provider,
		"pubsub":             facts.Platform.Pubsub,
		"secretStore":        facts.Platform.SecretStore,
	}
	// Only when unambiguous. Guessing between two brokers would put the wrong
	// name in a Component that the generated C# then fails to resolve.
	if len(facts.Model.PubSubs) == 1 {
		seeds["pubsubName"] = facts.Model.PubSubs[0].Name
	}
	if comp != nil {
		seeds["name"] = comp.Name
		seeds["kind"] = comp.Kind
		seeds["appId"] = comp.AppID
		seeds["workload"] = comp.Workload
		if comp.Dir != "" {
			seeds["sourceDir"] = comp.Dir
		}
	} else {
		seeds["name"] = dirName
		seeds["appId"] = dirName
	}
	return seeds
}

// seedDeclaredParams keeps only the seeds the template declares as parameters.
//
// An undeclared key would sail past JSON Schema validation and land in the value
// map anyway, which is how a template silently acquires a dependency nobody
// documented.
func seedDeclaredParams(tmpl *template.Template, seeds map[string]any) map[string]any {
	base := make(map[string]any, len(seeds))
	for _, f := range tmpl.Fields() {
		if v, ok := seeds[f.Name]; ok && !isBlank(v) {
			base[f.Name] = v
		}
	}
	return base
}

// isBlank drops an empty derived fact so the template's own default still
// applies: an unset platform.pubsub must not override `default: rabbitmq`.
func isBlank(v any) bool {
	s, ok := v.(string)
	return ok && s == ""
}

func (f manifestFacts) gitopsMap(component, env string) map[string]any {
	return map[string]any{
		"domain":             f.Domain,
		"system":             f.System,
		"component":          component,
		"env":                env,
		"host":               HostDirName,
		"registry":           f.Registry,
		"argocdAppNamespace": f.AppNamespace,
		"environments":       f.Environments,
		"platform": map[string]any{
			"provider":    f.Platform.Provider,
			"pubsub":      f.Platform.Pubsub,
			"secretStore": f.Platform.SecretStore,
		},
	}
}

// scaffoldValues is the component's recorded template values, or an empty map so
// a skeleton reading .scaffold.x never fails on a missing record.
func (f manifestFacts) scaffoldValues(component string) map[string]any {
	if s, ok := f.Scaffolds[component]; ok && s.Values != nil {
		return s.Values
	}
	return map[string]any{}
}

func toMap(v any) (map[string]any, error) {
	raw, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, err
	}
	return out, nil
}

type publishScaffoldOptions struct {
	StagingDir string
	Dest       *destTree
	Actions    []FileAction
	Rels       []string
	Branch     string
	Facts      manifestFacts
}

// publishedScaffold is what a successful push produced.
type publishedScaffold struct {
	Revision string

	// Placeholders are scanned from the working tree *while the branch is still
	// checked out*. Scanning afterwards would find nothing: restoring the default
	// branch takes the new files back out of the working tree.
	Placeholders []Placeholder
}

// publishScaffold writes the staged files on a fresh branch and pushes it.
//
// Never to the default branch: the tree is full of placeholders and unpinned
// images, and the ApplicationSet would generate Applications for it the moment it
// landed. A branch is the reviewable artefact.
//
// Publish is not reused: it is wired to a Plan and its rebase-retry loop is for a
// one-line contended edit. A fresh branch that is rejected already exists on the
// remote, which is a clear error rather than something to retry.
func publishScaffold(ctx context.Context, opts manifestRunOptions, repo *gitops.Repository, p publishScaffoldOptions) (publishedScaffold, error) {
	start := gitops.RemoteName + "/" + repo.Branch
	if err := repo.Git.CreateBranch(ctx, p.Branch, start); err != nil {
		return publishedScaffold{}, err
	}
	// Unconditionally, on success and on failure alike: the refresh on the next
	// Open resets whatever branch is current to the default branch's remote head,
	// so leaving the checkout here would silently discard these commits.
	defer func() {
		if err := repo.Git.Switch(ctx, repo.Branch); err != nil {
			fmt.Fprintf(opts.Stderr, "warning: could not restore %s in the cached checkout: %v\n", repo.Branch, err)
		}
	}()

	written, err := applyStaged(p.StagingDir, p.Dest, p.Actions)
	if err != nil {
		return publishedScaffold{}, err
	}
	// Only the paths staged, never `add -A`: the checkout is shared, and a
	// concurrent run's debris is not ours to commit.
	if err := repo.Git.Add(ctx, written...); err != nil {
		return publishedScaffold{}, err
	}
	// The scaffold is reviewed as a branch, and a reviewer reads the file list as
	// the whole of what this command did. It has to actually be that.
	if err := assertStagedIsExactly(ctx, repo.Git, written); err != nil {
		return publishedScaffold{}, err
	}
	subject := manifestCreateSubject(p.Facts, opts.reviewEnv, len(written))
	if err := repo.Git.Commit(ctx, subject, scaffoldTrailers(p.Facts, opts.reviewEnv, opts.CliVersion)); err != nil {
		return publishedScaffold{}, err
	}
	if err := assertCommittedIsExactly(ctx, repo.Git, written); err != nil {
		return publishedScaffold{}, err
	}
	if err := repo.Git.Push(ctx, gitops.RemoteName, "HEAD:refs/heads/"+p.Branch); err != nil {
		return publishedScaffold{}, fmt.Errorf("push %s: %w\n\nA rejection here usually means the branch already exists on the remote. Delete it, or merge the open review first.", p.Branch, err)
	}

	revision, err := repo.Git.HEAD(ctx)
	if err != nil {
		return publishedScaffold{}, err
	}
	// While the branch is still current — the deferred switch above takes these
	// files back out of the working tree.
	placeholders, err := scanPlaceholders(repo.Root, p.Rels)
	if err != nil {
		return publishedScaffold{}, err
	}
	return publishedScaffold{Revision: revision, Placeholders: placeholders}, nil
}

func manifestCreateSubject(facts manifestFacts, env string, files int) string {
	return fmt.Sprintf("manifests(%s): create %d %s file%s under %s", facts.System, files, env, plural(files), facts.Domain)
}

func scaffoldTrailers(facts manifestFacts, env, cliVersion string) string {
	trailers := []git.Trailer{
		{Key: TrailerDomain, Value: facts.Domain},
		{Key: TrailerSystem, Value: facts.System},
	}
	if env != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerEnvironment, Value: env})
	}
	for _, c := range facts.Selected {
		trailers = append(trailers, git.Trailer{Key: TrailerComponent, Value: c.Name})
	}
	if who := committer(); who != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerBy, Value: who})
	}
	if cliVersion != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerCli, Value: cliVersion})
	}

	lines := make([]string, 0, len(trailers))
	for _, t := range trailers {
		lines = append(lines, t.String())
	}
	return strings.Join(lines, "\n")
}

// reportManifestCreate writes the action table, then what remains to be done.
func reportManifestCreate(out output, result ManifestCreateResult, actions []FileAction, planOnly bool) error {
	if out.Format == OutputJSON {
		enc := json.NewEncoder(out.Stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(result); err != nil {
			return fmt.Errorf("write JSON result: %w", err)
		}
		return nil
	}

	for _, a := range actions {
		fmt.Fprintf(out.Stdout, "  %-12s %s\n", a.Action, a.Rel)
	}
	fmt.Fprintf(out.Stdout, "\n%s\n", summariseActions(actions))

	switch {
	case planOnly:
		fmt.Fprintln(out.Stdout, "nothing created (--dry-run)")
	case result.Applied:
		fmt.Fprintf(out.Stdout, "pushed branch %s at %s\n", result.Branch, git.ShortSHA(result.Revision))
	default:
		fmt.Fprintln(out.Stdout, "all manifest files already exist; nothing created")
	}

	reportPlaceholders(out, result.Placeholders)
	return nil
}

func conflictingPaths(actions []FileAction) []string {
	var out []string
	for _, a := range actions {
		if a.Action == ActionConflict {
			out = append(out, a.Rel)
		}
	}
	return out
}

func refuseManifestReplacements(actions []FileAction) error {
	conflicts := conflictingPaths(actions)
	if len(conflicts) == 0 {
		return nil
	}
	var lines []string
	for _, rel := range conflicts {
		lines = append(lines, "  "+rel)
	}
	return fmt.Errorf("%d manifest file%s already exist and differ:\n%s\nmanifests create never replaces files; edit the existing GitOps files or remove them before creating again",
		len(conflicts), plural(len(conflicts)), strings.Join(lines, "\n"))
}

func reportManifestCreateDiff(w io.Writer, staging string, dest *destTree, actions []FileAction) error {
	for _, action := range actions {
		if action.Action == ActionIdentical {
			continue
		}
		after, err := os.ReadFile(filepath.Join(staging, filepath.FromSlash(action.Rel)))
		if err != nil {
			return fmt.Errorf("read staged %s: %w", action.Rel, err)
		}
		before, err := dest.read(action.Rel)
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("read %s: %w", action.Rel, err)
		}
		diff := kustomize.Diff(before, after, action.Rel+" (current)", action.Rel+" (generated)", kustomize.PlainPalette)
		if diff != "" {
			fmt.Fprint(w, diff)
		}
	}
	return nil
}

package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// TemplateRoleLabel names the manifest label that declares what role a
	// template's output plays in a system. Its value is copied into the
	// scaffold record so later commands can tell support projects apart
	// from system blocks.
	TemplateRoleLabel = "intropy.dev/template-role"

	// RoleSharedLibrary marks a scaffolded project that exists to be
	// referenced by sibling components (e.g. shared models). System
	// assembly must not treat it as a block.
	RoleSharedLibrary = "shared-library"

	// RoleSystemHost marks the scaffolded host project of an integration
	// system. System assembly must not treat it as a block.
	RoleSystemHost = "system-host"

	// TemplateBlockKindLabel names the manifest label that declares which
	// Intropy block a template scaffolds (e.g. "extractor"). Its value is
	// copied into the scaffold record so `sys create` can assemble the
	// system declaration from what each scaffold recorded.
	TemplateBlockKindLabel = "intropy.dev/block-kind"

	// TemplateDataFlowLabel names the manifest label that declares the
	// block's data flow direction relative to the system ("in", "out",
	// or "both"). Recorded alongside the block kind.
	TemplateDataFlowLabel = "intropy.dev/data-flow"

	// The BlockKind constants name the block kinds with a parse entry in
	// internal/system's blockParsers registry — the set `sys create`
	// assembles. Records carrying any other kind are skipped with a
	// warning.
	BlockKindExtractor     = "extractor"
	BlockKindLoader        = "loader"
	BlockKindTransactional = "transactional-integration"
)

var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")

// Scaffold is the committed record of what `int create` rendered. Unlike
// CreateResult it carries no outputDir — the file's location is the project
// root — and it is written into the project so later commands (e.g. `sys
// create`) can re-fetch the exact template version.
type Scaffold struct {
	SchemaVersion int            `json:"schemaVersion"`
	Template      string         `json:"template"` // directory name in the template library repo
	Owner         string         `json:"owner"`
	Repo          string         `json:"repo"`
	Version       string         `json:"version"`
	Values        map[string]any `json:"values"`

	// Role is the value of the template's intropy.dev/template-role label,
	// if any (e.g. "shared-library").
	Role string `json:"role,omitempty"`

	// BlockKind is the value of the template's intropy.dev/block-kind
	// label, if any (e.g. "extractor").
	BlockKind string `json:"blockKind,omitempty"`

	// DataFlow is the value of the template's intropy.dev/data-flow label,
	// if any ("in" or "out").
	DataFlow string `json:"dataFlow,omitempty"`

	// DependsOn lists the sibling projects this project's template declared
	// under spec.dependencies, whether the render created them or they
	// already existed.
	DependsOn []DependencyRecord `json:"dependsOn,omitempty"`
}

// DependencyRecord points at a sibling project a component depends on. Dir
// is slash-separated and relative to the component root (e.g. "../Acme.Models").
type DependencyRecord struct {
	Template string `json:"template"`
	Dir      string `json:"dir"`
}

func roleFromLabels(labels map[string]string) string {
	return labels[TemplateRoleLabel]
}

func blockKindFromLabels(labels map[string]string) string {
	return labels[TemplateBlockKindLabel]
}

func dataFlowFromLabels(labels map[string]string) string {
	return labels[TemplateDataFlowLabel]
}

// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
func WriteScaffold(projectRoot string, s Scaffold) error {
	path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	return nil
}

// LoadScaffold reads and parses a scaffold.json file.
func LoadScaffold(path string) (*Scaffold, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
	}
	return &s, nil
}

// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
// Returns the parsed record and the project root that contains it, or
// ErrScaffoldNotFound if the filesystem root is reached first.
func FindScaffold(startDir string) (*Scaffold, string, error) {
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, "", fmt.Errorf("absolute path: %w", err)
	}

	for {
		candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(candidate); err == nil {
			s, err := LoadScaffold(candidate)
			if err != nil {
				return nil, "", err
			}
			return s, abs, nil
		} else if !os.IsNotExist(err) {
			return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
		}

		parent := filepath.Dir(abs)
		if parent == abs {
			return nil, "", ErrScaffoldNotFound
		}
		abs = parent
	}
}

package system

import "github.com/integrio-intropy/intropy-cli/internal/template"

// TopicKey identifies a topic within the system: the pub/sub component it
// lives on plus the topic name. Two scaffolds naming the same key declare
// the two halves of one contract. It aliases the canonical type in
// internal/template — there is one "which topic" concept across the CLI,
// shared by assembly and prompt-time facts.
type TopicKey = template.TopicKey

// Topic is one assembled topic: its key and the C# contract type its
// messages carry. The identifier it gets in the generated Topics class is
// derived by the template, not the CLI.
type Topic struct {
	TopicKey
	Contract string `json:"contract"`
}

// Component is one assembled system block. Its wiring is shape-driven:
// Topic is nil for kinds without one, and Ports carries the named ports in
// the kind's order (From before To for transactional blocks).
type Component struct {
	AppID string    `json:"name"` // the Add<Kind> argument in the generated system class
	Kind  string    `json:"kind"` // a key of the blockParsers registry
	Topic *TopicKey `json:"-"`    // nil for kinds without a topic
	// Port is the single port of a topic block; empty for records that
	// predate it. Kept alongside Ports so the --output-json summary stays
	// additive-only.
	Port  string   `json:"port,omitempty"`
	Ports []string `json:"ports,omitempty"` // transactional blocks: exactly [from, to]
	Path  string   `json:"path"`            // scaffold directory, for error messages

	// topicContract is the contract type of Topic, carried on the
	// component because topics dedupe across components: the model's
	// Topics list needs one contract per key, first seen wins.
	topicContract string
	// missingPort marks a topic-block record that predates the port value,
	// so Assemble can warn without failing the record.
	missingPort bool
}

// Port is one assembled port: the named edge a block reaches the outside
// world through. The declaration carries only the deployed transport shape;
// `sys create` resolves every port to a folder under the host's test/
// directory through the generated development definition. The identifier it
// gets in the generated Ports class is derived by the template, not the CLI.
type Port struct {
	Name string `json:"name"`
}

// SharedLibrary is the workspace's contract project: referenced by the
// host, never declared as a component.
type SharedLibrary struct {
	Path string // scaffold directory
	Name string // project name; also the namespace and csproj basename
}

